use gpui::{
    App, Application, Bounds, TitlebarOptions, WindowOptions, prelude::*, px, size,
};
use std::sync::{Arc, Mutex};

mod audio;
mod models;
mod state;
mod ui;

use audio::PipeWireEngine;
use models::MixerState;
use state::MixerGlobal;
use ui::MixerWindow;

fn main() {
    Application::new().run(|cx: &mut App| {
        // Set up channels
        let (event_tx, event_rx) = crossbeam_channel::unbounded();

        // Create the PipeWire engine
        let (engine, cmd_tx) = PipeWireEngine::new(event_tx);

        // Create global state
        let mixer_global = MixerGlobal {
            state: Arc::new(Mutex::new(MixerState::default())),
            event_rx,
            cmd_tx,
            engine,
        };

        cx.set_global(mixer_global);

        // Open window
        let window = cx
            .open_window(
                WindowOptions {
                    titlebar: Some(TitlebarOptions {
                        title: Some("MusicMixer".into()),
                        ..Default::default()
                    }),
                    window_bounds: Some(gpui::WindowBounds::Windowed(Bounds::centered(
                        None,
                        size(px(960.), px(680.)),
                        cx,
                    ))),
                    ..Default::default()
                },
                |_window, cx| {
                    cx.new(|_cx| MixerWindow::new())
                },
            )
            .unwrap();

        window
            .update(cx, |_view, _window, cx| {
                cx.activate(true);
            })
            .unwrap();
    });
}

use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum NodeType {
    App,          // Stream/Output/Audio — app playing audio
    AppInput,     // Stream/Input/Audio — app recording audio
    OutputDevice, // Audio/Sink — speakers, headphones
    InputDevice,  // Audio/Source — microphone
    VirtualBus,   // Null sink created by mixer
    Other,
}

#[derive(Debug, Clone)]
pub struct AudioNode {
    pub id: u32,
    pub name: String,
    pub description: String,
    pub node_type: NodeType,
    pub volume: f32,   // 0.0 - 1.0
    pub muted: bool,
}

#[derive(Debug, Clone)]
pub struct PortInfo {
    pub id: u32,
    pub node_id: u32,
    pub name: String,
    pub direction: PortDirection,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PortDirection {
    Input,
    Output,
}

#[derive(Debug, Clone)]
pub struct LinkInfo {
    pub id: u32,
    pub output_node: u32,
    pub input_node: u32,
    pub output_port: u32,
    pub input_port: u32,
}

#[derive(Debug, Clone, Default)]
pub struct MixerState {
    pub nodes: HashMap<u32, AudioNode>,
    pub ports: HashMap<u32, PortInfo>,
    pub links: HashMap<u32, LinkInfo>,
    pub node_ports: HashMap<u32, Vec<u32>>, // node_id -> port_ids
}

impl MixerState {
    pub fn playback_apps(&self) -> Vec<&AudioNode> {
        self.nodes
            .values()
            .filter(|n| matches!(n.node_type, NodeType::App))
            .collect()
    }

    pub fn output_devices(&self) -> Vec<&AudioNode> {
        self.nodes
            .values()
            .filter(|n| matches!(n.node_type, NodeType::OutputDevice | NodeType::VirtualBus))
            .collect()
    }

    pub fn input_devices(&self) -> Vec<&AudioNode> {
        self.nodes
            .values()
            .filter(|n| matches!(n.node_type, NodeType::InputDevice))
            .collect()
    }

    pub fn app_inputs(&self) -> Vec<&AudioNode> {
        self.nodes
            .values()
            .filter(|n| matches!(n.node_type, NodeType::AppInput))
            .collect()
    }

    pub fn is_linked(&self, from_node: u32, to_node: u32) -> bool {
        self.links.values().any(|l| {
            l.output_node == from_node && l.input_node == to_node
        })
    }

    pub fn find_links(&self, from_node: u32, to_node: u32) -> Vec<u32> {
        self.links
            .values()
            .filter(|l| l.output_node == from_node && l.input_node == to_node)
            .map(|l| l.id)
            .collect()
    }

    pub fn get_node_links(&self, node_id: u32) -> Vec<&LinkInfo> {
        self.links
            .values()
            .filter(|l| l.output_node == node_id || l.input_node == node_id)
            .collect()
    }

    pub fn get_output_ports(&self, node_id: u32) -> Vec<&PortInfo> {
        self.node_ports
            .get(&node_id)
            .map(|ids| {
                ids.iter()
                    .filter_map(|id| self.ports.get(id))
                    .filter(|p| matches!(p.direction, PortDirection::Output))
                    .collect()
            })
            .unwrap_or_default()
    }

    pub fn get_input_ports(&self, node_id: u32) -> Vec<&PortInfo> {
        self.node_ports
            .get(&node_id)
            .map(|ids| {
                ids.iter()
                    .filter_map(|id| self.ports.get(id))
                    .filter(|p| matches!(p.direction, PortDirection::Input))
                    .collect()
            })
            .unwrap_or_default()
    }
}

#[derive(Debug, Clone)]
pub enum EngineEvent {
    NodeAdded(AudioNode),
    NodeChanged(AudioNode),
    NodeRemoved(u32),
    PortAdded(PortInfo),
    PortRemoved(u32),
    LinkAdded(LinkInfo),
    LinkRemoved(u32),
    VolumeChanged { node_id: u32, volume: f32 },
    MuteChanged { node_id: u32, muted: bool },
}

#[derive(Debug, Clone)]
pub enum EngineCommand {
    SetVolume { node_id: u32, volume: f32 },
    SetMute { node_id: u32, muted: bool },
    CreateLink { from_node: u32, to_node: u32 },
    RemoveLinks { link_ids: Vec<u32> },
    LoadNullSink { name: String },
    UnloadModule { module_id: u32 },
}

