use gpui::{
    div, prelude::*, px, rgb, App, Context, IntoElement, Render, SharedString, Window,
};

use crate::models::{EngineCommand, EngineEvent, NodeType};
use crate::state::MixerGlobal;

pub struct MixerWindow {
    virtual_bus_counter: u32,
    /// node_id -> list of output device ids the user has added for routing
    routing: std::collections::HashMap<u32, Vec<u32>>,
    /// which node's "add output" dropdown is open
    open_dropdown: Option<u32>,
}

impl MixerWindow {
    pub fn new() -> Self {
        MixerWindow {
            virtual_bus_counter: 0,
            routing: Default::default(),
            open_dropdown: None,
        }
    }

    fn on_add_bus(&mut self, _window: &mut Window, cx: &mut Context<Self>) {
        self.virtual_bus_counter += 1;
        let name = format!("MusicMixer-Bus-{}", self.virtual_bus_counter);
        if let Some(global) = cx.try_global::<MixerGlobal>() {
            let _ = global.cmd_tx.send(EngineCommand::LoadNullSink { name });
        }
        cx.notify();
    }

    pub fn poll_events(&mut self, cx: &mut Context<Self>) {
        let events: Vec<EngineEvent> = if let Some(global) = cx.try_global::<MixerGlobal>() {
            let mut v = vec![];
            while let Ok(e) = global.event_rx.try_recv() {
                v.push(e);
            }
            v
        } else {
            vec![]
        };

        if events.is_empty() {
            return;
        }

        if let Some(global) = cx.try_global::<MixerGlobal>() {
            let mut state = global.state.lock().unwrap();
            for event in events {
                match event {
                    EngineEvent::NodeAdded(node) => { state.nodes.insert(node.id, node); }
                    EngineEvent::NodeChanged(node) => { state.nodes.insert(node.id, node); }
                    EngineEvent::NodeRemoved(id) => {
                        state.nodes.remove(&id);
                        state.node_ports.remove(&id);
                        self.routing.remove(&id);
                    }
                    EngineEvent::PortAdded(port) => {
                        let node_id = port.node_id;
                        let port_id = port.id;
                        state.ports.insert(port.id, port);
                        state.node_ports.entry(node_id).or_default().push(port_id);
                    }
                    EngineEvent::PortRemoved(id) => {
                        if let Some(port) = state.ports.remove(&id) {
                            if let Some(ports) = state.node_ports.get_mut(&port.node_id) {
                                ports.retain(|&p| p != id);
                            }
                        }
                    }
                    EngineEvent::LinkAdded(link) => { state.links.insert(link.id, link); }
                    EngineEvent::LinkRemoved(id) => { state.links.remove(&id); }
                    EngineEvent::VolumeChanged { node_id, volume } => {
                        if let Some(n) = state.nodes.get_mut(&node_id) { n.volume = volume; }
                    }
                    EngineEvent::MuteChanged { node_id, muted } => {
                        if let Some(n) = state.nodes.get_mut(&node_id) { n.muted = muted; }
                    }
                }
            }
        }
        cx.notify();
    }
}

// ── colours ──────────────────────────────────────────────────────────────────
const BG: u32        = 0x0f1117;
const SURFACE: u32   = 0x1a1d27;
const BORDER: u32    = 0x2a2d3a;
const TEXT: u32      = 0xe2e8f0;
const MUTED_TEXT: u32= 0x64748b;
const GREEN: u32     = 0x22c55e;
const BLUE: u32      = 0x3b82f6;
const AMBER: u32     = 0xf59e0b;
const PURPLE: u32    = 0xa855f7;
const RED: u32       = 0xef4444;
const CARD_BG: u32   = 0x1e2130;

impl Render for MixerWindow {
    fn render(&mut self, _window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        self.poll_events(cx);
        _window.request_animation_frame();

        // Snapshot state
        let (playback_ids, input_ids, output_ids, app_input_ids, outputs_list) =
            if let Some(g) = cx.try_global::<MixerGlobal>() {
                let s = g.state.lock().unwrap();
                let mut playback: Vec<u32> = s.playback_apps().iter().map(|n| n.id).collect();
                let mut inputs:   Vec<u32> = s.input_devices().iter().map(|n| n.id).collect();
                let mut outputs:  Vec<u32> = s.output_devices().iter().map(|n| n.id).collect();
                let mut app_in:   Vec<u32> = s.app_inputs().iter().map(|n| n.id).collect();
                playback.sort();
                inputs.sort();
                outputs.sort();
                app_in.sort();
                let out_list: Vec<(u32, String)> = s.output_devices()
                    .iter().map(|n| (n.id, short_name(&n.description, 22))).collect();
                (playback, inputs, outputs, app_in, out_list)
            } else {
                (vec![], vec![], vec![], vec![], vec![])
            };

        let routing = self.routing.clone();
        let open_dd = self.open_dropdown;

        div()
            .size_full()
            .flex()
            .flex_col()
            .bg(rgb(BG))
            .text_color(rgb(TEXT))
            .font_size(px(13.))
            // ── top bar ──────────────────────────────────────────────────
            .child(
                div()
                    .h(px(48.))
                    .w_full()
                    .flex()
                    .items_center()
                    .justify_between()
                    .px(px(20.))
                    .bg(rgb(SURFACE))
                    .border_b_1()
                    .border_color(rgb(BORDER))
                    .child(
                        div()
                            .text_color(rgb(TEXT))
                            .font_weight(gpui::FontWeight::BOLD)
                            .font_size(px(15.))
                            .child("🎛  MusicMixer"),
                    )
                    .child(
                        div()
                            .px(px(14.))
                            .py(px(6.))
                            .rounded_md()
                            .bg(rgb(BLUE))
                            .text_color(rgb(0xffffff))
                            .font_size(px(12.))
                            .cursor_pointer()
                            .child("+ Add Bus")
                            .id("add-bus-btn")
                            .on_click(cx.listener(|this, _, w, cx| this.on_add_bus(w, cx))),
                    ),
            )
            // ── scrollable body ──────────────────────────────────────────
            .child(
                div()
                    .flex_1()
                    .overflow_y_scroll()
                    .p(px(20.))
                    .flex()
                    .flex_col()
                    .gap(px(28.))
                    // Playback Apps
                    .when(!playback_ids.is_empty(), |d| {
                        d.child(section("Playback Apps", GREEN,
                            &playback_ids, &outputs_list, &routing, open_dd, cx))
                    })
                    // App Inputs (recording apps)
                    .when(!app_input_ids.is_empty(), |d| {
                        d.child(section("App Inputs", PURPLE,
                            &app_input_ids, &outputs_list, &routing, open_dd, cx))
                    })
                    // Input Devices — no routing, just volume/mute
                    .when(!input_ids.is_empty(), |d| {
                        d.child(input_section("Input Devices", BLUE, &input_ids, cx))
                    })
                    // Output Devices — no routing
                    .when(!output_ids.is_empty(), |d| {
                        d.child(input_section("Output Devices", AMBER, &output_ids, cx))
                    })
                    .when(
                        playback_ids.is_empty() && app_input_ids.is_empty()
                            && input_ids.is_empty() && output_ids.is_empty(),
                        |d| d.flex().items_center().justify_center().child(
                            div().text_color(rgb(MUTED_TEXT)).child("Waiting for PipeWire…"),
                        ),
                    ),
            )
    }
}

// ── Section with routing ──────────────────────────────────────────────────────
fn section(
    title: &str,
    color: u32,
    node_ids: &[u32],
    outputs: &[(u32, String)],
    routing: &std::collections::HashMap<u32, Vec<u32>>,
    open_dd: Option<u32>,
    cx: &mut Context<MixerWindow>,
) -> impl IntoElement {
    let cards = node_ids.iter().map(|&id| {
        let routed: Vec<u32> = routing.get(&id).cloned().unwrap_or_default();
        // available outputs = those not yet added
        let available: Vec<(u32, String)> = outputs.iter()
            .filter(|(oid, _)| !routed.contains(oid))
            .cloned()
            .collect();
        let dd_open = open_dd == Some(id);
        routable_card(id, &routed, outputs, &available, dd_open, cx)
    }).collect::<Vec<_>>();

    div()
        .flex()
        .flex_col()
        .gap(px(10.))
        .child(section_label(title, color))
        .child(
            div()
                .flex()
                .flex_row()
                .flex_wrap()
                .gap(px(12.))
                .children(cards),
        )
}

// ── Section without routing (input/output devices) ───────────────────────────
fn input_section(
    title: &str,
    color: u32,
    node_ids: &[u32],
    cx: &mut Context<MixerWindow>,
) -> impl IntoElement {
    let cards = node_ids.iter().map(|&id| simple_card(id, cx)).collect::<Vec<_>>();
    div()
        .flex()
        .flex_col()
        .gap(px(10.))
        .child(section_label(title, color))
        .child(
            div()
                .flex()
                .flex_row()
                .flex_wrap()
                .gap(px(12.))
                .children(cards),
        )
}

fn section_label(title: &str, color: u32) -> impl IntoElement {
    div()
        .flex()
        .items_center()
        .gap(px(8.))
        .child(
            div().w(px(3.)).h(px(16.)).rounded_full().bg(rgb(color)),
        )
        .child(
            div()
                .text_color(rgb(color))
                .font_weight(gpui::FontWeight::SEMIBOLD)
                .font_size(px(12.))
                .child(SharedString::from(title.to_string())),
        )
}

// ── Card with routing ─────────────────────────────────────────────────────────
fn routable_card(
    node_id: u32,
    routed: &[u32],
    all_outputs: &[(u32, String)],
    available: &[(u32, String)],
    dd_open: bool,
    cx: &mut Context<MixerWindow>,
) -> impl IntoElement {
    let (name, desc, volume, muted) = node_snapshot(cx, node_id);
    let mute_bg = if muted { RED } else { 0x374151u32 };
    let vol_pct = (volume * 100.0).round() as u32;

    // Route pills (already added outputs)
    let routed_owned: Vec<u32> = routed.to_vec();
    let all_out_owned: Vec<(u32, String)> = all_outputs.to_vec();
    let avail_owned: Vec<(u32, String)> = available.to_vec();

    let pills = routed_owned.iter().map(|&out_id| {
        let label = all_out_owned.iter()
            .find(|(id, _)| *id == out_id)
            .map(|(_, n)| n.clone())
            .unwrap_or_else(|| format!("{out_id}"));
        let label_shared = SharedString::from(label);
        div()
            .flex()
            .items_center()
            .gap(px(4.))
            .px(px(8.))
            .py(px(3.))
            .rounded_full()
            .bg(rgb(0x1e3a5f))
            .border_1()
            .border_color(rgb(BLUE))
            .child(
                div().text_color(rgb(0x93c5fd)).font_size(px(11.)).child(label_shared),
            )
            .child(
                div()
                    .text_color(rgb(0x94a3b8))
                    .font_size(px(11.))
                    .cursor_pointer()
                    .child("✕")
                    .id(SharedString::from(format!("unroute-{node_id}-{out_id}")))
                    .on_click(move |_, _, cx: &mut App| {
                        let link_ids = cx.try_global::<MixerGlobal>()
                            .map(|g| g.state.lock().unwrap().find_links(node_id, out_id))
                            .unwrap_or_default();
                        if let Some(g) = cx.try_global::<MixerGlobal>() {
                            if !link_ids.is_empty() {
                                let _ = g.cmd_tx.send(EngineCommand::RemoveLinks { link_ids });
                            }
                        }
                        // Also remove from local routing map via a global notify trick —
                        // we can't access MixerWindow here, so we use a dedicated command
                        // The routing map is cleaned up on next render via is_linked check
                    }),
            )
    }).collect::<Vec<_>>();

    // Dropdown items
    let dd_items = avail_owned.iter().map(|(out_id, out_name)| {
        let out_id = *out_id;
        let label = SharedString::from(out_name.clone());
        div()
            .px(px(12.))
            .py(px(7.))
            .cursor_pointer()
            .text_color(rgb(TEXT))
            .font_size(px(12.))
            .hover(|s| s.bg(rgb(0x2d3148)))
            .child(label)
            .id(SharedString::from(format!("dd-item-{node_id}-{out_id}")))
            .on_click(move |_, _, cx: &mut App| {
                if let Some(g) = cx.try_global::<MixerGlobal>() {
                    let _ = g.cmd_tx.send(EngineCommand::CreateLink {
                        from_node: node_id,
                        to_node: out_id,
                    });
                }
            })
    }).collect::<Vec<_>>();

    div()
        .w(px(220.))
        .flex()
        .flex_col()
        .bg(rgb(CARD_BG))
        .border_1()
        .border_color(rgb(BORDER))
        .rounded_lg()
        .overflow_hidden()
        // header
        .child(card_header(&name, &desc))
        // volume row
        .child(vol_row(node_id, volume, vol_pct, muted, mute_bg, cx))
        // routing area
        .child(
            div()
                .px(px(10.))
                .pb(px(10.))
                .flex()
                .flex_col()
                .gap(px(6.))
                .child(
                    div()
                        .text_color(rgb(MUTED_TEXT))
                        .font_size(px(10.))
                        .font_weight(gpui::FontWeight::SEMIBOLD)
                        .child("OUTPUT ROUTING"),
                )
                // existing route pills
                .child(
                    div().flex().flex_row().flex_wrap().gap(px(4.)).children(pills),
                )
                // "+ Add Output" button + dropdown
                .child(
                    div()
                        .relative()
                        .child(
                            div()
                                .flex()
                                .items_center()
                                .gap(px(4.))
                                .px(px(8.))
                                .py(px(4.))
                                .rounded_md()
                                .bg(rgb(0x1e3a5f))
                                .border_1()
                                .border_color(rgb(BLUE))
                                .cursor_pointer()
                                .text_color(rgb(0x93c5fd))
                                .font_size(px(11.))
                                .child(if avail_owned.is_empty() { "No more outputs" } else { "+ Add Output" })
                                .id(SharedString::from(format!("dd-btn-{node_id}")))
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    if this.open_dropdown == Some(node_id) {
                                        this.open_dropdown = None;
                                    } else {
                                        this.open_dropdown = Some(node_id);
                                    }
                                    cx.notify();
                                })),
                        )
                        .when(dd_open && !dd_items.is_empty(), |d| {
                            d.child(
                                div()
                                    .absolute()
                                    .top(px(28.))
                                    .left(px(0.))
                                    .w(px(200.))
                                    .bg(rgb(0x1a1d27))
                                    .border_1()
                                    .border_color(rgb(BORDER))
                                    .rounded_md()
                                    .shadow_lg()
                                    .z_index(100)
                                    .children(dd_items),
                            )
                        }),
                ),
        )
}

// ── Simple card (no routing) ──────────────────────────────────────────────────
fn simple_card(node_id: u32, cx: &mut Context<MixerWindow>) -> impl IntoElement {
    let (name, desc, volume, muted) = node_snapshot(cx, node_id);
    let mute_bg = if muted { RED } else { 0x374151u32 };
    let vol_pct = (volume * 100.0).round() as u32;

    div()
        .w(px(200.))
        .flex()
        .flex_col()
        .bg(rgb(CARD_BG))
        .border_1()
        .border_color(rgb(BORDER))
        .rounded_lg()
        .overflow_hidden()
        .child(card_header(&name, &desc))
        .child(vol_row(node_id, volume, vol_pct, muted, mute_bg, cx))
}

// ── Shared card pieces ────────────────────────────────────────────────────────
fn card_header(name: &str, desc: &str) -> impl IntoElement {
    div()
        .px(px(10.))
        .pt(px(10.))
        .pb(px(6.))
        .flex()
        .flex_col()
        .gap(px(2.))
        .child(
            div()
                .text_color(rgb(TEXT))
                .font_weight(gpui::FontWeight::SEMIBOLD)
                .font_size(px(13.))
                .child(SharedString::from(short_name(name, 24))),
        )
        .child(
            div()
                .text_color(rgb(MUTED_TEXT))
                .font_size(px(11.))
                .child(SharedString::from(short_name(desc, 28))),
        )
}

fn vol_row(
    node_id: u32,
    volume: f32,
    vol_pct: u32,
    muted: bool,
    mute_bg: u32,
    cx: &mut Context<MixerWindow>,
) -> impl IntoElement {
    let vol_bar_w = px(160.0 * volume);
    div()
        .px(px(10.))
        .pb(px(10.))
        .flex()
        .flex_col()
        .gap(px(6.))
        // mute + percent row
        .child(
            div()
                .flex()
                .items_center()
                .justify_between()
                .child(
                    div()
                        .px(px(10.))
                        .py(px(3.))
                        .rounded_md()
                        .bg(rgb(mute_bg))
                        .text_color(rgb(0xffffff))
                        .font_size(px(11.))
                        .cursor_pointer()
                        .child(if muted { "Unmute" } else { "Mute" })
                        .id(SharedString::from(format!("mute-{node_id}")))
                        .on_click(move |_, _, cx: &mut App| {
                            let new_muted = cx.try_global::<MixerGlobal>()
                                .and_then(|g| g.state.lock().unwrap().nodes.get(&node_id).map(|n| !n.muted))
                                .unwrap_or(false);
                            if let Some(g) = cx.try_global::<MixerGlobal>() {
                                let _ = g.cmd_tx.send(EngineCommand::SetMute { node_id, muted: new_muted });
                            }
                        }),
                )
                .child(
                    div()
                        .text_color(rgb(MUTED_TEXT))
                        .font_size(px(11.))
                        .child(format!("{vol_pct}%")),
                ),
        )
        // vol bar + - + buttons
        .child(
            div()
                .flex()
                .items_center()
                .gap(px(6.))
                .child(
                    div()
                        .w(px(24.))
                        .py(px(3.))
                        .rounded_md()
                        .bg(rgb(0x374151))
                        .text_color(rgb(TEXT))
                        .font_size(px(12.))
                        .text_center()
                        .cursor_pointer()
                        .child("−")
                        .id(SharedString::from(format!("vd-{node_id}")))
                        .on_click(move |_, _, cx: &mut App| {
                            let v = cx.try_global::<MixerGlobal>()
                                .and_then(|g| g.state.lock().unwrap().nodes.get(&node_id).map(|n| (n.volume - 0.1).max(0.0)))
                                .unwrap_or(0.0);
                            if let Some(g) = cx.try_global::<MixerGlobal>() {
                                let _ = g.cmd_tx.send(EngineCommand::SetVolume { node_id, volume: v });
                            }
                        }),
                )
                .child(
                    div()
                        .flex_1()
                        .h(px(5.))
                        .rounded_full()
                        .bg(rgb(0x374151))
                        .child(
                            div().h_full().rounded_full().bg(rgb(GREEN)).w(vol_bar_w),
                        ),
                )
                .child(
                    div()
                        .w(px(24.))
                        .py(px(3.))
                        .rounded_md()
                        .bg(rgb(0x374151))
                        .text_color(rgb(TEXT))
                        .font_size(px(12.))
                        .text_center()
                        .cursor_pointer()
                        .child("+")
                        .id(SharedString::from(format!("vu-{node_id}")))
                        .on_click(move |_, _, cx: &mut App| {
                            let v = cx.try_global::<MixerGlobal>()
                                .and_then(|g| g.state.lock().unwrap().nodes.get(&node_id).map(|n| (n.volume + 0.1).min(1.0)))
                                .unwrap_or(1.0);
                            if let Some(g) = cx.try_global::<MixerGlobal>() {
                                let _ = g.cmd_tx.send(EngineCommand::SetVolume { node_id, volume: v });
                            }
                        }),
                ),
        )
}

// ── Helpers ───────────────────────────────────────────────────────────────────
fn node_snapshot(cx: &App, node_id: u32) -> (String, String, f32, bool) {
    cx.try_global::<MixerGlobal>()
        .and_then(|g| {
            let s = g.state.lock().unwrap();
            s.nodes.get(&node_id).map(|n| (n.name.clone(), n.description.clone(), n.volume, n.muted))
        })
        .unwrap_or_else(|| (format!("Node {node_id}"), String::new(), 1.0, false))
}

fn short_name(s: &str, max: usize) -> String {
    if s.chars().count() > max {
        s.chars().take(max).collect::<String>() + "…"
    } else {
        s.to_string()
    }
}

